"use strict";
const cp=require('node:child_process'),assert=require('node:assert/strict');
const repo='BestNameYet/Terminals';
function gh(args){return JSON.parse(cp.execFileSync('gh',['api',...args],{encoding:'utf8',maxBuffer:8*1024*1024}));}
function read(path){try{const r=gh(['repos/'+repo+'/contents/'+path]);return {sha:r.sha,body:Buffer.from(r.content.replace(/\s/g,''),'base64').toString('utf8')};}catch(e){if(String(e).includes('404'))return null;throw e;}}
function write(path,body,old,msg){
 const args=['--method','PUT','repos/'+repo+'/contents/'+path,'-f','message='+msg,'-f','content='+Buffer.from(body).toString('base64'),'-f','branch=main'];
 if(old)args.push('-f','sha='+old.sha);
 const r=gh(args);const after=read(path);assert.equal(after.body,body);return r.commit?.sha;
}
const evidencePath="workspaces/extractor-srs-design/acceptance/E2E-008-DISTINCT-SHARES-20261103.md";
const evidence="# E2E-008 — concurrent extraction of two distinct public shares\n\n**Status:** PASS  \n**Date:** 2026-11-03  \n**Scope:** EXT-VERIFY-001 / E2E-008 only. Other functional, nonfunctional, and end-to-end acceptance requirements are not automatically certified by this result.\n\n## Input and dispatch evidence\n\nTwo GitHub Actions workflow_dispatch requests were launched concurrently through the authorized Terminals Issue #3 command interface ([submission comment 6606550338](https://github.com/BestNameYet/Terminals/issues/3#issuecomment-6606550338)). Both GitHub run records show `created_at = 2026-11-03T14:33:50Z` (zero-second creation-time separation). The workflow serializes publication using `terminals-shared-conversation-publication`, with `cancel-in-progress: false`.\n\n| Share UUID | Run | Source-linear nodes | Selected visible messages | Publication commit | Verified files |\n|---|---:|---:|---:|---|---:|\n| 6ae6b576-9fa8-83e8-a040-4091fe0218e3 | [41654917999](https://github.com/BestNameYet/Terminals/actions/runs/41654917999) | 1,302 | 186 | [dd3d20089678604c71e6f4e522a6e2052ad20be0](https://github.com/BestNameYet/Terminals/commit/dd3d20089678604c71e6f4e522a6e2052ad20be0) | 8 |\n| 6ae9dd85-7ff0-83e8-90c3-4592305a2362 | [41654917547](https://github.com/BestNameYet/Terminals/actions/runs/41654917547) | 5,912 | 592 | [2b0d75f33f707d137651824ba904c33ea24185da](https://github.com/BestNameYet/Terminals/commit/2b0d75f33f707d137651824ba904c33ea24185da) | 8 |\n\n## Independent verification\n\nThe independent auditor ran through [Issue #3 comment 6606622231](https://github.com/BestNameYet/Terminals/issues/3#issuecomment-6606622231). [Its committed result](../../terminalruns/GPT6_20261103_E2E008_distinct_independent_audit_20261103T143644503Z.json) contains `result: PASS`, `distinct_share_count: 2`, `verified_file_count: 16`, and `verified_attestations: 2`.\n\nFor both runs the audit checked: GitHub Actions conclusion `success`; receipt correlation with request ID, URL UUID, run ID, and destination; exactly eight expected output files under separate run-scoped paths; SHA-256 and size of every receipt-covered output; both independently downloaded final-attestation JSON artifacts; attested SHA-256 and sizes for all eight files; noncollision of output paths and publication commits; and the dispatch creation-time separation.\n\nThe first run committed to `workspaces/shared-conversations/6ae6b576-9fa8-83e8-a040-4091fe0218e3/41654917999-1/`; the second to `workspaces/shared-conversations/6ae9dd85-7ff0-83e8-90c3-4592305a2362/41654917547-1/`.\n\n## Verdict and limits\n\n**E2E-008: PASS.** The two different public-share dispatches were created in the same recorded second, both completed successfully, both pushed distinct eight-file commits, and all sixteen saved files passed independent hash/attestation checks. This is evidence for the specified concurrent-publication scenario; it does not prove every possible concurrency interleaving, future serialization format, privacy-policy approval, or the remaining acceptance matrix.\n";
const existing=read(evidencePath);
if(existing&&existing.body!==evidence)throw Error('Existing E2E-008 record differs: conflict requires review');
if(!existing)console.log(JSON.stringify({evidence_commit:write(evidencePath,evidence,null,'Record independently verified two-share E2E-008 acceptance'),path:evidencePath,verified:true}));
const path='workspaces/extractor-srs-design/VERIFICATION-PLAN.md';
const current=read(path);assert(current);
const old='**E2E-008 — concurrency:** Dispatch at least two public shares simultaneously, capture both run IDs, allow serial noncancelled publication, prove no overwritten paths and verify all required files for both outputs. **Status: NOT RUN**.';
const replacement='**E2E-008 — concurrency:** Dispatch at least two public shares simultaneously, capture both run IDs, allow serial noncancelled publication, prove no overwritten paths and verify all required files for both outputs. **Status: PASS** (2026-11-03; [independent two-share evidence](acceptance/E2E-008-DISTINCT-SHARES-20261103.md)).';
let updated=current.body;
if(updated.includes(old)) updated=updated.replace(old,replacement);
else if(!updated.includes(replacement)) throw Error('E2E-008 criterion text changed; refuse silent replacement');
const before='**Execution status:** **NOT RUN** for every proposed new Terminals test. Source-system historical runs described in Issue #4 are **not** recorded as results for these tests.';
const after='**Execution status (updated 2026-11-03):** E2E-008 PASS with independently committed evidence; other acceptance cases retain their recorded statuses. Historical source-system runs are not substituted as Terminals results.';
if(updated.includes(before))updated=updated.replace(before,after);
if(!updated.includes('## 9. Post-delivery execution addendum')){
 updated+='\n## 9. Post-delivery execution addendum (2026-11-03)\n\n[E2E-008](acceptance/E2E-008-DISTINCT-SHARES-20261103.md) passed for two distinct public shares dispatched in the same recorded second; all 16 repository output files and both final attestations independently verified. This does not imply that the remaining listed acceptance tests have passed.\n';
}
if(updated!==current.body)console.log(JSON.stringify({plan_commit:write(path,updated,current,'Update E2E-008 verification plan after independent PASS'),plan:path,verified:true}));
else console.log(JSON.stringify({plan:path,unchanged:true}));

